#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s1, s2;
    cin >> s1 >> s2;

    int n = s1.size();
    vector<int> blocked(n);
    for (int i = 0; i < n; ++i) {
        blocked[i] = (s1[i] != '0') | ((s2[i] != '0') << 1);
    }

    const int NEG = -1e9;
    vector<array<int, 4>> dp(n + 1);
    for (auto &state : dp) state.fill(NEG);
    dp[0][0] = 0;

    const pair<int, int> placements[] = {
        {3, 1}, {3, 2}, {1, 3}, {2, 3}
    };

    for (int i = 0; i < n; ++i) {
        for (int mask = 0; mask < 4; ++mask) {
            if (dp[i][mask] == NEG || (mask & blocked[i])) continue;

            dp[i + 1][0] = max(dp[i + 1][0], dp[i][mask]);

            if (i + 1 == n) continue;

            int unavailable = mask | blocked[i];
            for (auto [currentMask, nextMask] : placements) {
                if ((unavailable & currentMask) == 0 &&
                    (blocked[i + 1] & nextMask) == 0) {
                    dp[i + 1][nextMask] =
                        max(dp[i + 1][nextMask], dp[i][mask] + 1);
                }
            }
        }
    }

    cout << dp[n][0] << '\n';
    return 0;
}

