                if ((tile & unavailable) == 0) {
                    int nextMask = (tile >> 2) & 3;
                    dp[i + 1][nextMask] =
                        max(dp[i + 1][nextMask], dp[i][mask] + 1);
                }
            }
        }
    }

    cout << dp[n][0] << '\n';
