#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s1, s2;
    cin >> s1 >> s2;

    int n = s1.size();
    const int NEG = -1e9;
    array<int, 4> dp, nextDP;
    dp.fill(NEG);
    dp[0] = 0;

    const pair<int, int> shapes[] = {
        {3, 1}, {3, 2}, {1, 3}, {2, 3}
    };

    for (int i = 0; i < n; ++i) {
        nextDP.fill(NEG);

        int currentFree = (s1[i] == '0') | ((s2[i] == '0') << 1);
        int nextFree = 0;
        if (i + 1 < n) {
            nextFree = (s1[i + 1] == '0') | ((s2[i + 1] == '0') << 1);
        }

        for (int mask = 0; mask < 4; ++mask) {
            if (dp[mask] == NEG || (mask & ~currentFree)) continue;

            nextDP[0] = max(nextDP[0], dp[mask]);

            if (i + 1 >= n) continue;

            for (auto [currentRequired, nextRequired] : shapes) {
                if ((currentRequired & mask) == 0 &&
                    (currentRequired & currentFree) == currentRequired &&
                    (nextRequired & nextFree) == nextRequired) {
                    nextDP[nextRequired] =
                        max(nextDP[nextRequired], dp[mask] + 1);
                }
            }
        }

        dp = nextDP;
    }

    cout << dp[0] << '\n';
    return 0;
}

